fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    // If the input slice is empty, return an empty vector
    if numbers.is_empty() {
        return Vec::new();
    }

    // Calculate the size of the result vector
    let n = numbers.len();
    let mut result = Vec::with_capacity(2 * n - 1);

    // Fill the result vector with elements and delimiters
    for (i, &num) in numbers.iter().enumerate() {
        result.push(num); // Push the number
        if i < n - 1 { // Only push delimiter if it's not the last element
            result.push(delim);
        }
    }

    result
}